#!/usr/bin/env python3
import base64
import datetime
import fcntl
import hashlib
import os
import re
import shutil
import tempfile
from pathlib import Path

ROOT = Path('/var/www/azmednsk-preview')
BACKUPS = Path('/var/backups/azmednsk')
PEOPLE = (
    ('Мосина', 'Анастасия Павловна', 'mosina', 'a494b48464e77f7c2ca3b38e7a0c6f7e6f100dd3765e4718d902339c2b3304c5', ''),
    ('Башлыкова', 'Анастасия Александровна', 'bashlykova', '608112c93e59c6a1d5eab6770a3e529f6f67f5ef09235fbbc0d94d50876be0a0', ''),
)

def demand(condition, message):
    if not condition:
        raise ValueError(message)

def build_cards():
    cards = []
    photos = {}
    for surname, given, slug, digest, encoded in PEOPLE:
        name = surname + ' ' + given
        url = '/assets/team2-v1/ztl-' + slug + '-' + digest[:8] + '.webp'
        data = base64.b64decode(encoded, validate=True)
        demand(hashlib.sha256(data).hexdigest() == digest, 'Ошибка контрольной суммы: ' + name)
        photos[url] = data
        cards.append(
            f'<article class="person" tabindex="-1" id="person-{slug}" data-search="{name.lower()} зубной техник">'
            f'<img loading="lazy" decoding="async" src="{url}" alt="{name}" width="640" height="960">'
            f'<div class="copy"><h3>{surname}<span>{given}</span></h3><p>Зубной техник</p><small></small>'
            '<a href="#help">Уточнить у администратора →</a></div></article>'
        )
    return ''.join(cards), photos

def update_html(original, cards):
    sections = list(re.finditer(r'<section\b[^>]*\bid="laboratory"[^>]*>.*?</section>', original, re.S))
    demand(len(sections) == 1, 'Блок ЗТЛ отсутствует или повторяется')
    section = sections[0]
    marker = '</div><figure class="t2-photo'
    people, separator, gallery = section.group().partition(marker)
    demand(separator and people.endswith('</article>') and 'class="grid t2-people"' in people
           and 'Команда ЗТЛ' in gallery, 'Структура блока ЗТЛ изменилась')
    installed = people.endswith(cards)
    baseline = original.replace(cards, '', 1) if installed else original
    for surname, given, slug, _, _ in PEOPLE:
        demand(f'id="person-{slug}"' not in baseline and f'{surname} {given}'.casefold() not in baseline.casefold(),
               'Карточка уже существует в другом виде: ' + surname)
    if installed:
        return original
    offset = section.start() + len(people)
    return original[:offset] + cards + original[offset:]

def stage(path, data):
    with tempfile.NamedTemporaryFile(dir=path.parent, prefix='.ztl-', delete=False) as temp:
        temp.write(data)
        temp.flush()
        os.fsync(temp.fileno())
    return Path(temp.name)

def install(root, backups):
    page = root / 'team/index.html'
    folder = root / 'assets/team2-v1'
    demand(page.resolve() == page and folder.resolve() == folder and folder.is_dir(), 'Проверьте пути сайта')
    folder_fd = os.open(page.parent, os.O_RDONLY)
    try:
        fcntl.flock(folder_fd, fcntl.LOCK_EX)
        before = page.read_bytes()
        cards, photos = build_cards()
        after = update_html(before.decode('utf-8'), cards).encode('utf-8')
        missing = {}
        for url, data in photos.items():
            asset = root / url.lstrip('/')
            demand(not asset.is_symlink(), 'Символическая ссылка: ' + str(asset))
            if asset.exists():
                demand(asset.read_bytes() == data, 'Конфликт файла: ' + str(asset))
            else:
                missing[asset] = data
        if before == after and not missing:
            print('ZTL_TECHNICIANS=ALREADY_APPLIED')
            return
        stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
        backup = backups / ('team-ztl-' + stamp)
        backup.mkdir(mode=0o700, parents=True)
        shutil.copy2(page, backup / 'index.html')
        demand((backup / 'index.html').read_bytes() == before, 'Страница изменилась во время копирования')
        for asset, data in missing.items():
            temp = stage(asset, data)
            try:
                temp.chmod(0o644)
                os.link(temp, asset)
            finally:
                temp.unlink()
        if before != after:
            temp = stage(page, after)
            try:
                st = page.stat()
                if os.geteuid() == 0:
                    os.chown(temp, st.st_uid, st.st_gid)
                temp.chmod(st.st_mode & 0o7777)
                demand(page.read_bytes() == before, 'Страница изменилась, повторите запуск')
                os.replace(temp, page)
            finally:
                if temp.exists():
                    temp.unlink()
        demand(page.read_bytes() == after, 'Ошибка проверки страницы')
        for url, data in photos.items():
            demand((root / url.lstrip('/')).read_bytes() == data, 'Ошибка проверки ' + url)
        print('ZTL_TECHNICIANS=PASS; CARDS_ADDED=2; PHOTOS=VERIFIED')
        print('BACKUP=' + str(backup))
    finally:
        os.close(folder_fd)

if __name__ == '__main__':
    install(ROOT, BACKUPS)
    print('URL=https://azmednsk.ru/team/#laboratory')
